RESOLUTION_KEYS = frozenset(
    {
        "schema_version",
        "run_id",
        "problem_id",
        "condition",
        "mode",
        "semantics_mode",
        "k_workspace",
        "k_audit",
        "discovery_manifest",
        "klean_generation",
        "generation_producer_sources",
        "lean_workspace",
        "lean_invocation",
        "target",
        "stage1_source_hashes",
        "trust_inventory",
        "hashes",
        "selections",
        "stage4_preflight",
        "stage5_result",
    }
)


class Stage6ResolutionContractError(RuntimeError):
    """Raised when a Stage 6 signed resolution is malformed."""


def canonical_json_sha256(document: Any) -> str:
    encoded = json.dumps(
        document,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode()
    return hashlib.sha256(encoded).hexdigest()


def validate_sha256(value: object, label: str) -> str:
    if not isinstance(value, str) or re.fullmatch(
        r"[0-9a-f]{64}", value
    ) is None:
        raise Stage6ResolutionContractError(f"{label} is malformed")
    return value


def build_audit_input(
    resolution: dict[str, Any],
) -> dict[str, Any]:
    return {
        "schema_version": SCHEMA_VERSION,
        "resolution": resolution,
        "resolved_input_sha256": canonical_json_sha256(resolution),
    }


def verify_audit_input(
    document: dict[str, Any],
) -> tuple[dict[str, Any], str]:
    required = {
        "schema_version",
        "resolution",
        "resolved_input_sha256",
    }
    keys = set(document)
    if (
        (keys != required and keys != required | {"audit"})
        or document.get("schema_version") != SCHEMA_VERSION
    ):
        raise Stage6ResolutionContractError(
            "Stage 6 audit input envelope is malformed"
        )
    audit = document.get("audit")
    if "audit" in document and not isinstance(audit, dict):
        raise Stage6ResolutionContractError(
            "Stage 6 audit metadata is malformed"
        )
    resolution = document.get("resolution")
    if (
        not isinstance(resolution, dict)
        or set(resolution) != RESOLUTION_KEYS
        or resolution.get("schema_version") != SCHEMA_VERSION
    ):
        raise Stage6ResolutionContractError(
            "Stage 6 signed resolution is malformed"
        )
    digest = validate_sha256(
        document.get("resolved_input_sha256"),
        "Stage 6 resolved-input digest",
    )
    if canonical_json_sha256(resolution) != digest:
        raise Stage6ResolutionContractError(
            "Stage 6 audit input digest does not match signed resolution"
        )
    return resolution, digest
def sha256_tree(root: Path) -> str:
    root = require_real_directory(root, "tree root")
    digest = hashlib.sha256()
    pending = [root]
    entries: list[tuple[str, str, Path]] = []
    while pending:
        directory = pending.pop()
        try:
            children = list(os.scandir(directory))
        except OSError as error:
            raise PipelineContractError(f"cannot scan tree {directory}: {error}") from error
        for child in children:
            path = Path(child.path)
            try:
                mode = child.stat(follow_symlinks=False).st_mode
            except OSError as error:
                raise PipelineContractError(
                    f"cannot inspect tree entry {path}: {error}"
                ) from error
            relative = path.relative_to(root).as_posix()
            if stat.S_ISDIR(mode):
                entries.append((relative, "directory", path))
                pending.append(path)
            elif stat.S_ISREG(mode):
                entries.append((relative, "file", path))
            else:
                raise PipelineContractError(
                    f"tree contains linked or unsupported entry: {path}"
                )
    for relative, kind, path in sorted(entries):
        encoded = relative.encode()
        digest.update(len(encoded).to_bytes(4, "big"))
        digest.update(encoded)
        digest.update(kind.encode() + b"\0")
        if kind == "file":
            try:
                size = path.stat(follow_symlinks=False).st_size
                digest.update(size.to_bytes(8, "big"))
                with path.open("rb") as stream:
                    for chunk in iter(lambda: stream.read(_HASH_CHUNK_SIZE), b""):
                        digest.update(chunk)
            except OSError as error:
                raise PipelineContractError(
                    f"cannot hash tree file {path}: {error}"
                ) from error
    return digest.hexdigest()

